INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Dup hint', 'kz', 'Көлемі не салмағы әртүрлі болса да бір шикізат болады. Барлық рецепт, накладной, қалдық негізгіге көшеді, қалғаны өшеді. Керек емес топтың белгісін алыңыз.'), ('c2 Dup hint', 'ru', 'Даже с разным объёмом или весом это будет одно сырьё. Все рецепты, накладные и остатки переходят на основное, остальные удаляются. Снимите отметку с ненужных групп.'), ('c2 Dup hint', 'en', 'Even with different volume or weight it becomes one raw item. All recipes, waybills and stock move to the main one, the rest are deleted. Untick groups you do not want.'), ('c2 Dup hint', 'uz', 'Hajmi yoki og''irligi har xil bo''lsa ham bitta xomashyo bo''ladi. Barcha retsept, nakladnoy, qoldiq asosiyga o''tadi, qolganlari o''chiriladi. Keraksiz guruhlar belgisini oling.'), ('c2 Dup hint', 'ky', 'Көлөмү же салмагы ар башка болсо да бир чийки зат болот. Бардык рецепт, накладной, калдык негизгиге өтөт, калганы өчүрүлөт. Керексиз топтордун белгисин алыңыз.');
