INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('c2 Type hint', 'kz', 'Әртүрлі бренд / нұсқа бөлек қалады, бірақ бір түр болып көрінеді (Ун ▸ 3 нұсқа). Рецептте түр бағасы (соңғы накладной не орташа) қолданылады.'), ('c2 Type hint', 'ru', 'Разные бренды и варианты остаются отдельно, но показываются как один вид (Мука ▸ 3 варианта). В рецептах берётся цена вида (последняя накладная или средняя).'), ('c2 Type hint', 'en', 'Different brands and variants stay separate but show as one type (Flour ▸ 3 variants). Recipes use the type price (last waybill or average).'), ('c2 Type hint', 'uz', 'Turli brend va variantlar alohida qoladi, lekin bitta tur bo''lib ko''rinadi (Un ▸ 3 variant). Retseptda tur narxi (oxirgi nakladnoy yoki o''rtacha) olinadi.'), ('c2 Type hint', 'ky', 'Ар кандай бренд жана варианттар өзүнчө калат, бирок бир түр болуп көрүнөт (Ун ▸ 3 вариант). Рецептте түр баасы (акыркы накладной же орточо) колдонулат.');
